pub struct ReplaceInProjectUseCase {
    uow_factory: Box<dyn ReplaceInProjectUnitOfWorkFactoryTrait>,
    /// The Work's entity tree either side of the batch. One `restore_work` puts the
    /// manuscript back exactly as it was, however many scenes were rewritten.
    snap_before: Option<EntityTreeSnapshot>,
    snap_after: Option<EntityTreeSnapshot>,
}

impl ReplaceInProjectUseCase {
    pub fn new(uow_factory: Box<dyn ReplaceInProjectUnitOfWorkFactoryTrait>) -> Self {
        ReplaceInProjectUseCase {
            uow_factory,
            snap_before: None,
            snap_after: None,
        }
    }

    pub fn execute(&mut self, dto: &ReplaceInProjectDto) -> Result<ReplaceInProjectResultDto> {
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        // Replace across the caller-named Work only: Search hangs off this
        // Work's own WorkInfo, found via its `work` back-pointer.
        let work_id = dto.work_id as EntityId;
        let work_info: WorkInfo = uow
            .get_all_work_info()?
            .into_iter()
            .find(|wi| wi.work == Some(work_id))
            .ok_or_else(|| anyhow!("work {work_id} is not open"))?;
        let search: Search = uow
            .get_search(&work_info.search)?
            .ok_or_else(|| anyhow!("replace_in_project: WorkInfo has no Search"))?;
        if search.query.is_empty() {
            return Err(anyhow!("replace_in_project: nothing to replace (no query)"));
        }
        let work: Work = uow
            .get_all_work()?
            .into_iter()
            .find(|w| w.id == work_id)
            .ok_or_else(|| anyhow!("work {work_id} is not open"))?;

        // The rows the writer reviewed, minus the ones they unticked.
        let excluded: HashSet<EntityId> = dto.excluded_result_ids.iter().copied().collect();
        let result_ids =
            uow.get_search_relationship(&work_info.search, &SearchRelationshipField::Results)?;
        let rows: Vec<SearchResult> = uow
            .get_search_result_multi(&result_ids)?
            .into_iter()
            .flatten()
            .filter(|r| !excluded.contains(&r.id))
            .collect();

        // The language every item is written in, resolved per item (own tag, else the Work) over
        // the binder's ORDERED stream — through the same function `run_search` used to find
        // these rows. Two copies of that chain would drift, and a writer would meet the
        // drift as a rename that found a word under one set of rules and rewrote it under
        // another.
        //
        // Re-derived here rather than carried on the `SearchResult` row, for the same
        // reason the offsets are: a row records what the writer *reviewed*, and the
        // manuscript may have moved since.
        let languages = Self::resolve_languages(&mut uow, &work)?;

        // Snapshot AFTER the read-only planning above and BEFORE the first mutation —
        // the discipline `empty_trash` follows.
        let snap_before = uow.snapshot_work(&[work.id])?;

        let mut occurrences_replaced = 0u64;
        let mut skipped_stale: Vec<u64> = Vec::new();
        // ITEMS, not fields. A scene whose body AND synopsis both match is one item —
        // the confirm dialog says "across N items", and it must not say two.
        let mut touched_items: HashSet<EntityId> = HashSet::new();

        for row in &rows {
            // The scene's own language, and it decides two things — both of which a
            // profile-blind rename gets wrong, silently:
            //
            //   * what MATCHES. In Turkish `Ilse` and `İlse` are different words, and a
            //     rename that folded them together would rewrite the wrong one.
            //   * what the preserved case IS. The untailored uppercase of `i` is `I`, which
            //     in Turkish is the capital of the *other* letter — so `ilk` would become
            //     `ILK` where the prose needs `İLK`.
            let tags = languages
                .get(&row.binder_item_id)
                .cloned()
                .unwrap_or_default();
            // Folding is monolingual, so fold under the primary (first) tag — the language
            // the scene is chiefly written in. `FindOptions` takes the same single tag.
            let tag = crate::language::primary(&tags).to_string();
            let locale = FoldLocale::from_tag(&tag);

            // The same criteria, in the two shapes the two surfaces take: `find_opts` for a
            // parsed `BatchDocument`, `opts` for a plain string (a title, a label).
            //
            // Both are fed by the SAME `Search` entity and both resolve to the same shared
            // matcher underneath, so they cannot disagree about what counts as a match — a
            // rename that renamed a scene's prose but not its title would be exactly the
            // kind of half-done edit this use case exists to prevent.
            let find_opts = FindOptions {
                case_sensitive: search.case_sensitive,
                whole_word: search.whole_word,
                diacritic_sensitive: search.diacritic_sensitive,
                language: tag,
                // Regex is not exposed in the UI (a novelist is not the audience), and it
                // would need its own invalid-pattern handling and a second matching path.
                use_regex: false,
                search_backward: false,
            };
            let opts = MatchOptions {
                case_sensitive: search.case_sensitive,
                whole_word: search.whole_word,
                diacritic_sensitive: search.diacritic_sensitive,
                locale,
            };

            // How each individual occurrence is rewritten. With `preserve_case`, a rename
            // keeps the case it found (AURÉLIEN → AURÉLIAN, not aurélian).
            let case_of = |matched: &str| -> String {
                if dto.preserve_case {
                    text_document::matching::preserve_case(matched, &dto.replacement, locale)
                } else {
                    dto.replacement.clone()
                }
            };

            match row.match_field {
                // Titles and labels are plain strings on the item, not Djot Content —
                // no parser involved, so this is a direct string rewrite.
                MatchField::Title | MatchField::Label => {
                    let Some(item) = uow.get_binder_item(&row.binder_item_id)? else {
                        skipped_stale.push(row.id);
                        continue;
                    };
                    let mut item: BinderItem = item;
                    let current = match row.match_field {
                        MatchField::Title => item.title.clone(),
                        _ => item.label.clone(),
                    };
                    let hits = crate::matching::occurrences(&current, &search.query, opts);
                    if hits.len() as u64 != row.occurrence_count {
                        // The field moved under us since the writer reviewed it.
                        skipped_stale.push(row.id);
                        continue;
                    }
                    let rewritten =
                        crate::matching::replace_all(&current, &search.query, opts, case_of);
                    match row.match_field {
                        MatchField::Title => item.title = rewritten,
                        _ => item.label = rewritten,
                    }
                    uow.update_binder_item(&item)?;
                    touched_items.insert(row.binder_item_id);
                    occurrences_replaced += hits.len() as u64;
                }
                // A comment's own body, or one reply's. Plain strings on their own
                // rows — no Djot, no parser — so this is the same direct rewrite as
                // a title, against the ids the row carries rather than a Content.
                //
                // These rows only ever arrive here when the writer ticked them: the
                // UI excludes every comment hit by default, so renaming a character
                // cannot quietly edit the notes that discuss the old name. The guard
                // below is the same one prose gets — a body edited since review is
                // skipped and reported, never rewritten from a stale count.
                MatchField::Comment | MatchField::CommentReply => {
                    let is_reply = matches!(row.match_field, MatchField::CommentReply);
                    let current = if is_reply {
                        match uow.get_comment_reply(&row.reply_id)? {
                            Some(r) => r.body,
                            None => {
                                skipped_stale.push(row.id);
                                continue;
                            }
                        }
                    } else {
                        match uow.get_comment(&row.comment_id)? {
                            Some(c) => c.body,
                            None => {
                                skipped_stale.push(row.id);
                                continue;
                            }
                        }
                    };
                    let hits = crate::matching::occurrences(&current, &search.query, opts);
                    if hits.len() as u64 != row.occurrence_count {
                        skipped_stale.push(row.id);
                        continue;
                    }
                    let rewritten =
                        crate::matching::replace_all(&current, &search.query, opts, case_of);
                    if is_reply {
                        let Some(mut reply): Option<CommentReply> =
                            uow.get_comment_reply(&row.reply_id)?
                        else {
                            skipped_stale.push(row.id);
                            continue;
                        };
                        reply.body = rewritten;
                        uow.update_comment_reply(&reply)?;
                    } else {
                        let Some(mut comment): Option<Comment> =
                            uow.get_comment(&row.comment_id)?
                        else {
                            skipped_stale.push(row.id);
                            continue;
                        };
                        comment.body = rewritten;
                        uow.update_comment(&comment)?;
                    }
                    // Deliberately NOT added to `touched_items`: that set drives the
                    // per-item "this scene changed" reporting, and a comment is not
                    // the scene. An orphaned thread has no item to name at all.
                    occurrences_replaced += hits.len() as u64;
                }
                // Prose. Spliced INSIDE the document — never surgery on the markup.
                MatchField::Body | MatchField::Synopsis | MatchField::Epigraph => {
                    let Some(mut content) = Self::content_of(&mut uow, row)? else {
                        skipped_stale.push(row.id);
                        continue;
                    };
                    let batch = BatchDocument::new()?;
                    batch.set_djot(&content.data, &DjotImportOptions::default())?;

                    // Re-derive the matches inside the document. Never trust a position
                    // captured at review time — if the count no longer matches what the
                    // writer reviewed, the scene moved under us and we refuse it.
                    let hits = batch.find_all(&search.query, &find_opts)?;
                    if hits.len() as u64 != row.occurrence_count {
                        skipped_stale.push(row.id);
                        continue;
                    }
                    if hits.is_empty() {
                        continue;
                    }

                    // The splice happens in the DOCUMENT, at the offsets the parser itself
                    // reports (see the module doc for why this isn't a string rewrite), and
                    // the result is re-serialised by the exporter. `PreserveIfFullyCovered`
                    // keeps the styling of a name that was wholly styled, falling back to
                    // the previous behaviour when the range is only partly styled rather
                    // than guessing.
                    let replaced = batch.find_and_replace(
                        &search.query,
                        &ReplaceOptions::new(find_opts.clone())
                            .with_format_policy(ReplaceFormatPolicy::PreserveIfFullyCovered),
                        |matched, _| Some(case_of(matched)),
                    )?;

                    content.data = batch.to_djot(&DjotExportOptions::default())?;
                    uow.update_content(&content)?;
                    touched_items.insert(row.binder_item_id);
                    occurrences_replaced += replaced as u64;
                }
            }
        }

        // Every row we just rewrote now describes prose that no longer exists — its
        // snippet and its occurrence count are both lies. Drop the result set rather
        // than leave the UI listing matches it can no longer find (and rather than let
        // a second Replace All run against rows that would all read as stale).
        if !result_ids.is_empty() {
            uow.remove_search_result_multi(&result_ids)?;
        }

        let snap_after = uow.snapshot_work(&[work.id])?;
        uow.commit()?;
        uow.publish_replace_in_project_event(rows.iter().map(|r| r.binder_item_id).collect(), None);

        self.snap_before = Some(snap_before);
        self.snap_after = Some(snap_after);

        Ok(ReplaceInProjectResultDto {
            items_changed: touched_items.len() as u64,
            occurrences_replaced,
            skipped_stale,
        })
    }

    /// The language tag of every item in the Work, resolved per item (own tag, else the Work).
    ///
    /// The chain runs over each binder's **ordered** item stream — "the book an item is in"
    /// is the most recent `Book` before it, because the binder tree is organisational only
    /// and book structure is a state machine over the flat stream. Delegated to
    /// [`crate::language`], which is the *same* function `run_search` used to find these
    /// rows: a second copy would drift, and the drift would show up as a rename that found
    /// a word under one set of rules and rewrote it under another.
    fn resolve_languages(
        uow: &mut Box<dyn ReplaceInProjectUnitOfWorkTrait>,
        work: &Work,
    ) -> Result<HashMap<EntityId, Vec<String>>> {
        let mut tags = HashMap::new();
        let binder_ids = uow.get_work_relationship(&work.id, &WorkRelationshipField::Binders)?;
        for binder in uow.get_binder_multi(&binder_ids)?.into_iter().flatten() {
            let item_ids =
                uow.get_binder_relationship(&binder.id, &BinderRelationshipField::BinderItems)?;
            let items: Vec<BinderItem> = uow
                .get_binder_item_multi(&item_ids)?
                .into_iter()
                .flatten()
                .collect();
            crate::language::tags_in_binder(&work.dict_language, &items, &mut tags);
        }
        Ok(tags)
    }

    /// The `Content` row a result points at, matched by its role.
    fn content_of(
        uow: &mut Box<dyn ReplaceInProjectUnitOfWorkTrait>,
        row: &SearchResult,
    ) -> Result<Option<Content>> {
        let ids = uow.get_binder_item_relationship(
            &row.binder_item_id,
            &BinderItemRelationshipField::Contents,
        )?;
        Ok(uow
            .get_content_multi(&ids)?
            .into_iter()
            .flatten()
            .find(|c| {
                // The same mapping `run_search_uc` recorded the result with, inverted.
                // Shared rather than restated so the two cannot drift: a role findable
                // under one field and replaceable under another silently rewrites the
                // wrong row, or skips every hit.
                crate::match_field::role_matches_field(&row.match_field, &c.role)
            }))
    }
}

use common::undo_redo::UndoRedoCommand;

/// **One undo entry for the whole batch.** `restore_work` puts the Work's entity tree
/// back exactly as it was — every scene, every title — in a single step, however many
/// were rewritten. This is the entire safety story for Replace All: a writer who runs a
/// rename across 847 occurrences and does not like the result gets their manuscript back
/// in one action, not 847.
impl UndoRedoCommand for ReplaceInProjectUseCase {
    fn undo(&mut self) -> Result<()> {
        let snap = self
            .snap_before
            .as_ref()
            .ok_or_else(|| anyhow!("replace_in_project: nothing to undo"))?;
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;
        uow.restore_work(snap)?;
        uow.commit()?;
        Ok(())
    }

    fn redo(&mut self) -> Result<()> {
        let snap = self
            .snap_after
            .as_ref()
            .ok_or_else(|| anyhow!("replace_in_project: nothing to redo"))?;
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;
        uow.restore_work(snap)?;
        uow.commit()?;
        Ok(())
    }

    fn as_any(&self) -> &dyn Any {
        self
    }
}
